// R20 STAGE A - the tangent panels. Seven slabs standing against the +Y wall,
// z 16..144, each 60 wide with an 8 gap, their -Y face turned into the room.
//
// All seven carry the SAME texture, so they share one image and one derived
// normal map. Only the UV transform on the test face differs. That is the whole
// point: the derived map is a constant, the tangent basis is the variable, and
// anything that changes between panels is the basis and nothing else.
//
// The bump direction on every panel must agree with the texture's own light and
// dark. If panel 2 (90 deg) is lit from the opposite side to panel 0, the
// tangent is mirrored - which is the defect an axis-aligned wall cannot show,
// and the reason this row exists at all.
//
// Read them with a rocket, not with the static lighting: stand at the -X end of
// the row and fire along it, so one moving light sweeps all seven in one pass
// and they are directly comparable. The map's two light entities are baked into
// the lightmap at compile time and Stage A does not touch them.
	// panel 0 - 0 deg - the baseline the other six are read against
{
( -174 256 144 ) ( -174 240 144 ) ( -234 240 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( -174 240 16 ) ( -174 256 16 ) ( -234 256 16 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( -174 256 16 ) ( -174 256 144 ) ( -234 256 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( -234 240 16 ) ( -234 240 144 ) ( -174 240 144 ) qltest/tangent 0 0 0 0.250000 0.250000 0 0 0	// <- the test face
( -174 240 16 ) ( -174 240 144 ) ( -174 256 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( -234 256 16 ) ( -234 256 144 ) ( -234 240 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
}
// panel 1 - 45 deg
{
( -106 256 144 ) ( -106 240 144 ) ( -166 240 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( -106 240 16 ) ( -106 256 16 ) ( -166 256 16 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( -106 256 16 ) ( -106 256 144 ) ( -166 256 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( -166 240 16 ) ( -166 240 144 ) ( -106 240 144 ) qltest/tangent 0 0 45 0.250000 0.250000 0 0 0	// <- the test face
( -106 240 16 ) ( -106 240 144 ) ( -106 256 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( -166 256 16 ) ( -166 256 144 ) ( -166 240 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
}
// panel 2 - 90 deg - the case a mirrored tangent gets wrong and 0 deg hides
{
( -38 256 144 ) ( -38 240 144 ) ( -98 240 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( -38 240 16 ) ( -38 256 16 ) ( -98 256 16 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( -38 256 16 ) ( -38 256 144 ) ( -98 256 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( -98 240 16 ) ( -98 240 144 ) ( -38 240 144 ) qltest/tangent 0 0 90 0.250000 0.250000 0 0 0	// <- the test face
( -38 240 16 ) ( -38 240 144 ) ( -38 256 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( -98 256 16 ) ( -98 256 144 ) ( -98 240 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
}
// panel 3 - 135 deg
{
( 30 256 144 ) ( 30 240 144 ) ( -30 240 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( 30 240 16 ) ( 30 256 16 ) ( -30 256 16 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( 30 256 16 ) ( 30 256 144 ) ( -30 256 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( -30 240 16 ) ( -30 240 144 ) ( 30 240 144 ) qltest/tangent 0 0 135 0.250000 0.250000 0 0 0	// <- the test face
( 30 240 16 ) ( 30 240 144 ) ( 30 256 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( -30 256 16 ) ( -30 256 144 ) ( -30 240 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
}
// panel 4 - 30 deg at 0.25 x 0.125 - rotation plus anisotropy is a real shear
{
( 98 256 144 ) ( 98 240 144 ) ( 38 240 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( 98 240 16 ) ( 98 256 16 ) ( 38 256 16 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( 98 256 16 ) ( 98 256 144 ) ( 38 256 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( 38 240 16 ) ( 38 240 144 ) ( 98 240 144 ) qltest/tangent 0 0 30 0.250000 0.125000 0 0 0	// <- the test face
( 98 240 16 ) ( 98 240 144 ) ( 98 256 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( 38 256 16 ) ( 38 256 144 ) ( 38 240 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
}
// panel 5 - qlNoPerturb - the opt-out. Must stay flat.
{
( 166 256 144 ) ( 166 240 144 ) ( 106 240 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( 166 240 16 ) ( 166 256 16 ) ( 106 256 16 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( 166 256 16 ) ( 166 256 144 ) ( 106 256 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( 106 240 16 ) ( 106 240 144 ) ( 166 240 144 ) qltest/noperturb 0 0 0 0.250000 0.250000 0 0 0	// <- the test face
( 166 240 16 ) ( 166 240 144 ) ( 166 256 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( 106 256 16 ) ( 106 256 144 ) ( 106 240 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
}
// panel 6 - lightmap stage first, so the collapsed lighting bundle is bundle 1
{
( 234 256 144 ) ( 234 240 144 ) ( 174 240 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( 234 240 16 ) ( 234 256 16 ) ( 174 256 16 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( 234 256 16 ) ( 234 256 144 ) ( 174 256 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( 174 240 16 ) ( 174 240 144 ) ( 234 240 144 ) qltest/lightmapfirst 0 0 0 0.250000 0.250000 0 0 0	// <- the test face
( 234 240 16 ) ( 234 240 144 ) ( 234 256 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
( 174 256 16 ) ( 174 256 144 ) ( 174 240 144 ) ct_ragnarok/rock_03 0 0 0 0.500000 0.500000 0 0 0
}
}
// entity 1 - the light this map exists to keep. Off to one side and high, so
// the rock is lit from a direction rather than from directly above, which is
// what makes faceting obvious.
{
"classname" "light"
"origin" "-160 -160 224"
"light" "600"
"_color" "1.0 0.95 0.85"
}
// entity 2 - a second, dimmer fill from the far side, so the shadowed faces are
// not pure black and the shading gradient is readable across the whole form
{
"classname" "light"
"origin" "192 192 200"
"light" "250"
"_color" "0.75 0.82 1.0"
}
// entity 3
{
"classname" "info_player_deathmatch"
"origin" "-192 -192 32"
"angle" "45"
}
